  "/icu/",
  "/icu/pages.json",
  "/one-pagers/",
  "/one-pagers/pages.json",
  "/papers/",
  "/papers/pages.json",
  "/skills/",
  "/skills/skills.json",
  "/talks/fresh-gas-flow/",
  "/talks/general-anesthetic-case-flow/",
  "/talks/intoxicated-patient/",
  "/talks/intro-ct-rotation/",
  "/talks/local-anesthetics/",
